deco.css:
.fd-lantern{position:fixed;top:0;right:2vw;width:56px;height:74px;border-radius:50%/38% 38% 46% 46%;background:radial-gradient(circle at 42% 34%,rgba(232,185,35,.60),rgba(200,16,46,.34) 56%,rgba(200,16,46,.10));box-shadow:0 0 22px rgba(232,185,35,.30);animation:fd-swing 9s ease-in-out infinite;pointer-events:none}
.fd-lantern2{position:fixed;top:1vh;right:5vw;width:34px;height:46px;border-radius:50%/38% 38% 46% 46%;background:radial-gradient(circle at 42% 34%,rgba(232,185,35,.42),rgba(200,16,46,.22) 58%,rgba(200,16,46,.06));opacity:.8;pointer-events:none}
.fd-tassel{position:fixed;top:8.6vh;right:2.9vw;width:2px;height:1.2vh;background:linear-gradient(180deg,rgba(232,185,35,.7),rgba(232,185,35,0));pointer-events:none}
.fd-gold{position:fixed;left:0;bottom:0;width:100%;height:4vh;background:repeating-linear-gradient(90deg,rgba(232,185,35,.18) 0 8px,rgba(232,185,35,0) 8px 20px);pointer-events:none}
@keyframes fd-swing{0%,100%{transform:rotate(-2.2deg)}50%{transform:rotate(2.2deg)}}
@media (prefers-reduced-motion: reduce){.fd-lantern{animation:none}}
